-- GRAIN: one row per person (CL_PERSON_ID+DATE_CREATED+DATE_MODIFIED+YEAR+ID unique)
-- SPINE_ENTITY: person  (natural_key: PERSON_ID, DATE_CREATED, DATE_MODIFIED, YEAR, ID)
-- Generated by scripts/generate_staging_models.py from SOURCE_REGISTRY -- deterministic,
-- no LLM. Casts kept as landed (TEXT) -- add explicit type casts by hand once each
-- column's real type is confirmed; this generator has no semantic type knowledge.
-- spine_entity 'person' has no connect/ resolver yet (see connect/spine_entity.py) -- no SPINE_ENTITY_ID emitted.
-- landing table's ingestion timestamp is named INGESTED_AT (no leading underscore) rather than the usual _INGESTED_AT -- confirmed via INFORMATION_SCHEMA, not assumed.

with source as (

    select * from {{ source('ripple_raw', 'FED_COURTLISTENER_FINANCIAL_DISCLOSURES') }}

),

renamed as (

    select
        "ID" as id,
        "DATE_CREATED" as date_created,
        "DATE_MODIFIED" as date_modified,
        "YEAR" as year,
        "DOWNLOAD_FILEPATH" as download_filepath,
        "FILEPATH" as filepath,
        "THUMBNAIL" as thumbnail,
        "THUMBNAIL_STATUS" as thumbnail_status,
        "PAGE_COUNT" as page_count,
        "SHA1" as sha1,
        "REPORT_TYPE" as report_type,
        "IS_AMENDED" as is_amended,
        "ADDENDUM_CONTENT_RAW" as addendum_content_raw,
        "ADDENDUM_REDACTED" as addendum_redacted,
        "HAS_BEEN_EXTRACTED" as has_been_extracted,
        "PERSON_ID" as person_id,
        INGESTED_AT as _loaded_at,
        '' as _source_url

    from source

)

select * from renamed
qualify row_number() over (partition by person_id, date_created, date_modified, year, id order by _loaded_at desc) = 1
